// Bounded ParGeo-style logarithmic batch-dynamic point forest; see package README/LICENSE.
use std::slice;
#[derive(Clone,Copy)] struct BdkNode { id:usize,left:i32,right:i32,minx:i64,maxx:i64,miny:i64,maxy:i64 }
const EMPTY_NODE:BdkNode=BdkNode{id:0,left:-1,right:-1,minx:0,maxx:0,miny:0,maxy:0};
fn bdk_build(ids:&mut [usize],depth:usize,x:&[i64;32],y:&[i64;32],nodes:&mut [BdkNode;32],used:&mut usize)->i32{
    if ids.is_empty(){return -1;}let axis=depth&1;ids.sort_by_key(|&id|if axis==0{(x[id],y[id],id)}else{(y[id],x[id],id)});let mid=ids.len()/2;let (left,rest)=ids.split_at_mut(mid);let (center,right)=rest.split_at_mut(1);let id=center[0];let at=*used;*used+=1;nodes[at].id=id;
    let l=bdk_build(left,depth+1,x,y,nodes,used);let r=bdk_build(right,depth+1,x,y,nodes,used);nodes[at].left=l;nodes[at].right=r;nodes[at].minx=x[id];nodes[at].maxx=x[id];nodes[at].miny=y[id];nodes[at].maxy=y[id];
    for child in [l,r]{if child>=0{let c=nodes[child as usize];nodes[at].minx=nodes[at].minx.min(c.minx);nodes[at].maxx=nodes[at].maxx.max(c.maxx);nodes[at].miny=nodes[at].miny.min(c.miny);nodes[at].maxy=nodes[at].maxy.max(c.maxy);}}at as i32
}
fn bdk_box(n:BdkNode,qx:i64,qy:i64)->i64{let dx=if qx<n.minx{n.minx-qx}else if qx>n.maxx{qx-n.maxx}else{0};let dy=if qy<n.miny{n.miny-qy}else if qy>n.maxy{qy-n.maxy}else{0};dx*dx+dy*dy}
fn bdk_query(at:i32,nodes:&[BdkNode;32],x:&[i64;32],y:&[i64;32],active:&[bool;32],qx:i64,qy:i64,best:&mut Option<(i64,usize)>){if at<0{return;}let n=nodes[at as usize];if best.is_some_and(|b|bdk_box(n,qx,qy)>b.0){return;}let id=n.id;if active[id]{let dx=x[id]-qx;let dy=y[id]-qy;let candidate=(dx*dx+dy*dy,id);if best.is_none_or(|b|candidate<b){*best=Some(candidate);}}let mut children=[n.left,n.right];if children[0]>=0&&children[1]>=0&&bdk_box(nodes[children[1] as usize],qx,qy)<bdk_box(nodes[children[0] as usize],qx,qy){children.swap(0,1);}for child in children{bdk_query(child,nodes,x,y,active,qx,qy,best);}}
fn bdk_insert(levels:&mut [[usize;32];6],sizes:&mut [usize;6],id:usize){let mut carry=[0_usize;32];carry[0]=id;let mut count=1;for level in 0..6{if sizes[level]==0{levels[level][..count].copy_from_slice(&carry[..count]);sizes[level]=count;return;}let mut next=[0_usize;32];let mut next_count=0;for i in 0..sizes[level]{next[next_count]=levels[level][i];next_count+=1;}for i in 0..count{next[next_count]=carry[i];next_count+=1;}sizes[level]=0;carry[..next_count].copy_from_slice(&next[..next_count]);count=next_count;}}
#[no_mangle]
pub unsafe extern "C" fn batch_dynamic_kd_tree(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{
    if input.is_null()||length<2||length>250{return -1;}let values=slice::from_raw_parts(input,length);let initial0=values[0];if initial0<0||initial0>8||length<2+3*initial0 as usize{return -1;}
    let mut x=[0_i64;32];let mut y=[0_i64;32];let mut answers=[0_i64;8];let mut ever=[false;32];let mut active=[false;32];let mut levels=[[0_usize;32];6];let mut sizes=[0_usize;6];let mut pos=1;let mut inserted=0;
    for _ in 0..initial0 as usize{let id0=values[pos];let px=values[pos+1];let py=values[pos+2];pos+=3;if id0<0||id0>=32||ever[id0 as usize]||!(-1000..=1000).contains(&px)||!(-1000..=1000).contains(&py){return -1;}let id=id0 as usize;for j in 0..32{if active[j]&&x[j]==px&&y[j]==py{return -1;}}x[id]=px;y[id]=py;ever[id]=true;active[id]=true;inserted+=1;bdk_insert(&mut levels,&mut sizes,id);}
    if pos>=length{return -1;}let batch0=values[pos];pos+=1;if batch0<1||batch0>8{return -1;}let batches=batch0 as usize;
    for batch in 0..batches{if pos+2>length{return -1;}let kind=values[pos];let count0=values[pos+1];pos+=2;if (kind!=0&&kind!=1)||count0<1||count0>8{return -1;}let count=count0 as usize;
        if kind==0{if inserted+count>32||pos+3*count+2>length{return -1;}let records_start=pos;for j in 0..count{let id0=values[pos];let px=values[pos+1];let py=values[pos+2];pos+=3;if id0<0||id0>=32||ever[id0 as usize]||!(-1000..=1000).contains(&px)||!(-1000..=1000).contains(&py){return -1;}let id=id0 as usize;for t in 0..32{if active[t]&&x[t]==px&&y[t]==py{return -1;}}for t in 0..j{if values[records_start+3*t+1]==px&&values[records_start+3*t+2]==py{return -1;}}x[id]=px;y[id]=py;ever[id]=true;active[id]=true;inserted+=1;bdk_insert(&mut levels,&mut sizes,id);}}
        else{if pos+count+2>length{return -1;}for _ in 0..count{let id0=values[pos];pos+=1;if id0<0||id0>=32||!active[id0 as usize]{return -1;}active[id0 as usize]=false;}}
        if pos+2>length{return -1;}let qx=values[pos];let qy=values[pos+1];pos+=2;if !(-1000..=1000).contains(&qx)||!(-1000..=1000).contains(&qy){return -1;}let mut best:Option<(i64,usize)>=None;for level in 0..6{if sizes[level]>0{let mut ids=levels[level][..sizes[level]].to_vec();let mut nodes=[EMPTY_NODE;32];let mut used=0;let root=bdk_build(&mut ids,0,&x,&y,&mut nodes,&mut used);bdk_query(root,&nodes,&x,&y,&active,qx,qy,&mut best);}}let Some((distance,_))=best else{return -1;};answers[batch]=distance;
    }
    if pos!=length{return -1;}let needed=8*batches;if output.is_null()||capacity<needed{return -2;}let out=slice::from_raw_parts_mut(output,capacity);for i in 0..needed{out[i]=(answers[i/8]>>(8*(i%8))) as u8;}needed as i64
}
